var n=`0579-oshi-palav`;var t=`world-0579`;var o=`TJ`;var r=`central-asia`;var a=4;var l=108;var s={en:`Oshi Palav`,ua:`Оші палав`};var u={en:`A traditional dish from Tajikistan, centered on lamb, yellow onion, carrot, garlic. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Таджикистан. Основні складники: ягнятина, жовта цибуля, морква, часник. Домашній варіант із кількостями продуктів за етапами приготування.`};var g=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 14 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 14 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:14,i:[[`lamb`,750,`g`],[`yellow-onion`,240,`g`],[`sunflower-oil`,70,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 55 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 55 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:55,i:[[`carrot`,580,`g`],[`ground-cumin`,6,`g`],[`garlic`,4,`clove`],[`water`,620,`ml`]]},{en:`Spread the rice evenly into the flavorful liquid. Cook uncovered or partly covered for about 27 minutes until the liquid is absorbed; do not over-stir.`,ua:`Рівномірно розподіліть рис у ароматній рідині. Готуйте приблизно 27 хвилин до вбирання рідини, не перемішуючи надмірно.`,t:[`rice-washing`,`absorption-cooking`],m:27,i:[[`basmati-rice`,470,`g`]]},{en:`Take off the heat and let the rice rest under a clean towel or lid for about 12 minutes before serving.`,ua:`Зніміть із вогню та дайте рису відпочити під чистим рушником або кришкою приблизно 12 хвилин перед подаванням.`,t:[`rice-resting`,`fluffing-grains`],m:12,i:[]}];var d={slug:n,id:t,country:`TJ`,region:r,servings:4,minutes:108,title:s,text:u,steps:g};export{o as country,d as default,t as id,l as minutes,r as region,a as servings,n as slug,g as steps,u as text,s as title};